CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.menu_categories (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL CHECK(length(trim(name)) > 0), position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.menu_categories TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.menu_categories TO authenticated;
GRANT ALL ON public.menu_categories TO service_role;
ALTER TABLE public.menu_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public categories" ON public.menu_categories FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Admin categories" ON public.menu_categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.menu_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) > 0), category_id text NOT NULL REFERENCES public.menu_categories(id) ON DELETE RESTRICT, description text NOT NULL DEFAULT '', price numeric NOT NULL CHECK(price >= 0), old_price numeric CHECK(old_price > price), image text NOT NULL DEFAULT 'espresso', available boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.menu_items TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.menu_items TO authenticated;
GRANT ALL ON public.menu_items TO service_role;
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public available items" ON public.menu_items FOR SELECT TO anon,authenticated USING(available);
CREATE POLICY "Admin items" ON public.menu_items FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
